/**
 * rapidhash test vectors for all four published versions, from
 * `komiya-atsushi/rapidhash-js`'s `packages/rapidhash-js/test/test-vectors/`.
 *
 * Those files are *generated*: that project's `packages/gen-test/` compiles the reference C at a
 * named git revision and hashes a fixed corpus, and each file records the revision it came from.
 * So this is a differential check against the reference implementation rather than a
 * self-consistency test -- which is what replaced the earlier finding that rapidhash had no
 * reachable published value. It did; it was in a JavaScript port nobody had looked at.
 *
 * Revisions, one per version:
 *
 * - v1.0: `588978411df8683777429f729be5213eb1bfd5f3`
 * - v2.0: `0d48fd50149dbef269ed97d63f24d14c14b57973`
 * - v2.2: `cd62a6b899c96ef32dff14e61452e658acb3a783`
 * - v3.0: `bc4b4baa48a15ff52ff4725e1ccdcda62815221c`
 *
 * Two axes of coverage, and the second is the one that matters:
 *
 * - **short**: eight messages at four seeds each. Byte lengths 0, 1, 2, 3, 13 and 27, including
 *   multi-byte UTF-8, so the 1-to-3-byte gather and the 4-to-8 and 8-to-16 paths are all reached.
 * - **long**: prefixes of a fixed ASCII text at every branch boundary *and its neighbours* -- 4, 8,
 *   16, 32, 48, 56, 64, 80, 96, 112, 224 and 336, each at -1, exact and +1. Every difference
 *   between the four versions is a boundary (v2.0 switches branch at 56 where v2.2 switches at
 *   64, for one), so only a length either side of one can tell them apart.
 *
 * The `fast` rapid_mum behaviour throughout. `protected` is implemented in `rapidhash.ts` and not
 * offered as a tool -- see that file's header.
 */

export interface RapidhashShortVector {
  /** The message as text; the tool hashes its UTF-8 bytes. */
  readonly message: string;
  readonly seed: bigint;
  readonly expected: bigint;
}

export interface RapidhashLongVector {
  /** Bytes of `RAPIDHASH_LONG_TEXT` to hash, taken from the front. */
  readonly length: number;
  readonly seed: bigint;
  readonly expected: bigint;
}

export interface RapidhashVersionVectors {
  readonly version: string;
  /** The git revision of the reference C these were generated from. */
  readonly revision: string;
  readonly short: readonly RapidhashShortVector[];
  readonly long: readonly RapidhashLongVector[];
}

